import{_ as a,C as n,o as i,c as o,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.5","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.5","type":"implementation-case","domain":"TMPA","version":"I0.5","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.5.md","filePath":"en/publications/implementation-case-i0.5.md","lastUpdated":1785916356000}'),s={name:"en/publications/implementation-case-i0.5.md"};function c(l,e,p,u,h,m){const t=n("ArticleCover");return i(),o("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"The S0.4 engineering baseline and a WP-13 multi-agent evidence-gating and fact-checking case.",version:"I0.5",status:"S0.4 engineering evidence draft",languageHref:"/zh/publications/implementation-case-i0.5",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="s0-4-reference-reader-fcop-codeflowmu-and-the-wp-13-multi-agent-fact-check" tabindex="-1">S0.4 Reference Reader, FCoP, CodeFlowMu, and the WP-13 Multi-Agent Fact Check <a class="header-anchor" href="#s0-4-reference-reader-fcop-codeflowmu-and-the-wp-13-multi-agent-fact-check" aria-label="Permalink to &quot;S0.4 Reference Reader, FCoP, CodeFlowMu, and the WP-13 Multi-Agent Fact Check&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.5<br><strong>Status:</strong> Author-Produced Implementation and Case Report<br><strong>Normative Target:</strong> TMPA Core S0.4<br><strong>Historical Evidence Baseline:</strong> I0.3 / S0.3 corpus<br><strong>Report and Execution Date:</strong> 2026-08-03; WP-13 case observed 2026-08-05<br><strong>Conformance Corpus:</strong> <code>tmpa-s0.4-fcop-codeflowmu-20260803</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. TMPA Core requirements are defined only by the GitHub Core Specification.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This report advances the implementation case from an unavailable S0.3-era archive to a public, executable S0.4 corpus. I0.5 retains the I0.4 Reference Reader, C01–C14 fixtures, manifests, result envelopes, product-evidence assertions, and one-command runner, and adds the WP-13 field case. In that case, a subexecution produced a completion-meaning claim without confirmed exit status, tests, commit, or formal report. PM withheld release on persistent facts; DEV then completed the same task after tool recovery, followed by role-separated QA.</p><p>The FCoP protocol defines a project-visible coordination profile in which routed textual artifacts, lifecycle paths, atomic rename, append-only transition evidence, role bindings, reviews, issues, alerts, and inspection reports remain available outside transient sessions. Its reference implementation provides bounded executable evidence for those rules. CodeFlowMu adopts the protocol for persistent work identities, task/report flows, review gates, dependency waiting, recovery, and archival history. XiaoDian AI contributes pre-specification field evidence from a governed NL2SQL pipeline, including retained pass and rejection paths.</p><p>The S0.4 Reference Reader reports <strong>14 PASS</strong> against its author-produced synthetic fixture suite. The separately evaluated FCoP–CodeFlowMu product baseline remains <strong>1 PASS, 9 PARTIAL, 4 NOT RUN, and 0 FAIL</strong>, with aggregate verdict <code>PARTIAL</code>. WP-13 strengthens author-produced <code>demonstrated</code> evidence related to C04, C06, C07, and C13, but it did not execute a new S0.4 product-reader criterion. The verdicts are therefore not relabeled, and no independent-validation claim is made.</p><h1 id="_1-scope-and-evidence-boundary" tabindex="-1">1. Scope and Evidence Boundary <a class="header-anchor" href="#_1-scope-and-evidence-boundary" aria-label="Permalink to &quot;1. Scope and Evidence Boundary&quot;">​</a></h1><p>This report asks what the S0.4 Reference Reader implements, what the fixed product evidence demonstrates, and which S0.4 product requirements remained unexecuted. It is evidentiary and nonnormative. Its verdicts are preserved against the historical S0.4 target; the current <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a> defines current requirements and canonical test meanings, and I0.5 does not claim S0.5 conformance. The <a href="/joinwell52/en/publications/tmpa-architecture-paper-a0.5">Architecture Paper A0.5</a> explains the theory.</p><p>Evidence classes remain <strong>specified</strong>, <strong>implemented</strong>, <strong>demonstrated</strong>, and <strong>independently adopted</strong>. The Reference Reader is implemented and author-demonstrated. The product baseline contains mixed implemented/demonstrated evidence and remains <code>PARTIAL</code>. Fixture success is not converted into FCoP or CodeFlowMu product conformance, and no independent-adoption or independent-validation claim is made.</p><h1 id="_2-engineering-lineage-and-component-boundaries" tabindex="-1">2. Engineering Lineage and Component Boundaries <a class="header-anchor" href="#_2-engineering-lineage-and-component-boundaries" aria-label="Permalink to &quot;2. Engineering Lineage and Component Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT CONCEPTUAL LAYERING</span></span>
<span class="line"><span>TMPA architecture → reusable FCoP protocol profile → CodeFlowMu and other applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HISTORICAL LINEAGE</span></span>
<span class="line"><span>XiaoDian AI practice → original TMPA → FCoP extraction and maturation</span></span>
<span class="line"><span>                    → CodeFlowMu application → current TMPA formalization</span></span></code></pre></div><p>FCoP defines a protocol profile over a file-based subset of TMPA semantics. The <code>fcop</code> and <code>fcop-mcp</code> packages are its reference implementation; CodeFlowMu is a downstream application that adopts the protocol as coordination and governance infrastructure. FCoP does not exhaust TMPA; CodeFlowMu does not define FCoP; XiaoDian AI is lineage and field evidence rather than a product-level TMPA reader.</p><p>Terminology follows Section 2 of the Core Specification. In particular, <strong>governance object</strong> is a semantic unit, <strong>source artifact</strong> is a physical observation, <strong>governance reader</strong> is the deterministic reconstruction stage, and <code>valid</code> / <code>invalid</code> / <code>undetermined</code> are the only semantic governance judgments. This report does not introduce alternative meanings.</p><p>FCoP uses ordinary filesystem artifacts and operating-system operations as a project-visible coordination surface. CodeFlowMu combines FCoP operations with agent sessions, runtime scheduling, role interfaces, business workflows, approval paths, recovery controls, and user-facing views. XiaoDian AI contributes permission, validation, NL2SQL, policy-gate, rejection, and audit evidence.</p><h1 id="_3-fcop-protocol-and-reference-implementation-evidence" tabindex="-1">3. FCoP Protocol and Reference-Implementation Evidence <a class="header-anchor" href="#_3-fcop-protocol-and-reference-implementation-evidence" aria-label="Permalink to &quot;3. FCoP Protocol and Reference-Implementation Evidence&quot;">​</a></h1><h2 id="_3-1-durable-textual-message-and-state-surface" tabindex="-1">3.1 Durable Textual Message and State Surface <a class="header-anchor" href="#_3-1-durable-textual-message-and-state-surface" aria-label="Permalink to &quot;3.1 Durable Textual Message and State Surface&quot;">​</a></h2><p>FCoP treats the project filesystem as a durable textual message and state surface: <strong>files carry protocol, paths address state, and events replay transitions</strong>. A routed <code>TASK-*</code> artifact serves as a stable work anchor; reports, reviews, issues, alerts, and decisions are separate linked artifacts; filenames carry routing metadata; lifecycle directories expose current state; atomic rename performs lifecycle movement; transition evidence records how state was reached; and artifacts remain inspectable after the originating session ends.</p><h2 id="_3-2-agent-visible-role-binding" tabindex="-1">3.2 Agent-Visible Role Binding <a class="header-anchor" href="#_3-2-agent-visible-role-binding" aria-label="Permalink to &quot;3.2 Agent-Visible Role Binding&quot;">​</a></h2><p>Governed participation begins with an explicit role binding visible to the agent. It identifies active role, collaboration context, scope, permitted/prohibited actions, and independent review or escalation roles. This is operational protocol identity, not cryptographic or legal identity.</p><h2 id="_3-3-lifecycle" tabindex="-1">3.3 Lifecycle <a class="header-anchor" href="#_3-3-lifecycle" aria-label="Permalink to &quot;3.3 Lifecycle&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox → active → review → done → archive → history</span></span>
<span class="line"><span>           ↑        |</span></span>
<span class="line"><span>           └─ reject┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Action</th><th>Source</th><th>Target</th><th>Typical authority</th></tr></thead><tbody><tr><td><code>create_task</code></td><td>—</td><td><code>inbox</code></td><td>task creator</td></tr><tr><td><code>claim_task</code></td><td><code>inbox</code></td><td><code>active</code></td><td>assigned executor</td></tr><tr><td><code>submit_task</code></td><td><code>active</code></td><td><code>review</code></td><td>responsible executor</td></tr><tr><td><code>approve_task</code></td><td><code>review</code></td><td><code>done</code></td><td>reviewer or approver</td></tr><tr><td><code>reject_task</code></td><td><code>review</code></td><td><code>active</code></td><td>reviewer</td></tr><tr><td><code>finish_task</code></td><td><code>active</code></td><td><code>done</code></td><td>profile-authorized role</td></tr><tr><td><code>archive_task</code></td><td><code>done</code></td><td><code>archive</code></td><td>archival authority</td></tr><tr><td><code>archive_to_history</code></td><td><code>archive</code></td><td><code>history/...</code></td><td>archival authority</td></tr></tbody></table><p>Path represents current state under the profile; transition evidence records history. Inconsistency is an issue, not silently repaired state.</p><h2 id="_3-4-routing-atomic-publication-and-recovery" tabindex="-1">3.4 Routing, Atomic Publication, and Recovery <a class="header-anchor" href="#_3-4-routing-atomic-publication-and-recovery" aria-label="Permalink to &quot;3.4 Routing, Atomic Publication, and Recovery&quot;">​</a></h2><p>A reference filename is <code>{TYPE}-{YYYYMMDD}-{NNN}-{SENDER}-to-{RECIPIENT}(-slug).md</code>. Filename is transport envelope; body and schema carry complete meaning. Atomic publication uses write-to-temporary and rename where supported. Recovery reconstructs task identity, current lifecycle, responsibility, linked evidence, unresolved dependencies, and issues from persistent artifacts rather than hidden session context.</p><h1 id="_4-codeflowmu-as-a-persistent-work-environment" tabindex="-1">4. CodeFlowMu as a Persistent-Work Environment <a class="header-anchor" href="#_4-codeflowmu-as-a-persistent-work-environment" aria-label="Permalink to &quot;4. CodeFlowMu as a Persistent-Work Environment&quot;">​</a></h1><p>CodeFlowMu explores a persistent AI work role—sometimes called a digital employee—as an engineering identity that accepts delegated work, uses tools, and submits evidence across sessions. The term does not imply legal employment, personhood, consciousness, human intention, or replacement of the accountable human or organization.</p><p>Model and session instances may change while governed work identity continues through role bindings, task/thread identifiers, reports and reviews, approval/rejection records, lifecycle transitions, unresolved issues/dependencies, recovery, and archival evidence.</p><p>One observed session illustrates the distinction between protocol initialization and participant identity. FCoP was initialized, but the session had not been assigned a role. The agent requested explicit role binding before establishing the development plan. After receiving a PM/co-reviewer binding it acknowledged the role and created governed planning work. The observation establishes operational role visibility, not cryptographic authentication.</p><p>Observed and tested CodeFlowMu paths include ADMIN/PM delegation, executor claim and execution, separate report submission, QA/governance review, approval/rejection/human-attention states, dependency waiting and release, ISSUE creation, restart recovery, archival history, lifecycle authority, fact gates, state history, and operation approval.</p><p>The implementation can block release when required evidence is missing, stale, or incomplete. Current local findings are not yet normalized into one TMPA canonical issue set and evidence graph. CodeFlowMu maintains session, task, report, lifecycle, and ledger evidence sufficient to demonstrate selected restart and recovery behaviors, but no single product reader currently reconstructs responsibility, lifecycle, unresolved dependencies, conflicts, and issues into one canonical output. This is why C13 remains PARTIAL.</p><h1 id="_5-xiaodian-ai-nl2sql-worked-case" tabindex="-1">5. XiaoDian AI NL2SQL Worked Case <a class="header-anchor" href="#_5-xiaodian-ai-nl2sql-worked-case" aria-label="Permalink to &quot;5. XiaoDian AI NL2SQL Worked Case&quot;">​</a></h1><p>A public TMPA-oriented browser demonstration is available at <code>https://demo.chedian.cc/</code>. The data-producing private development system and public repository are not asserted to be one directly reproducible build; the public view is an observable deployment snapshot, not a complete reproduction package.</p><p>A 2026-07-29 snapshot displayed 330 Profile, 16,129 Event, 924 Message, 1,220 Index/Export, 44 Knowledge, and 352 Audit records. These counts describe one captured state and are not performance benchmarks.</p><p>The visible NL2SQL chain included authorization, intent normalization, schema retrieval, DDL-context loading, model-based SQL generation, read-only validation, write blocking, table whitelisting, tenant isolation, field/join/enumeration validation, and result-reasonableness checking.</p><p>Two captured chains were reported: a vehicle-violation query passed in 26,344 ms; a vehicle-expense summary query was rejected after 131,994 ms. The evidence value is the retained divergence between accepted and rejected paths. The sample is too small and selected to support rates or representative performance claims.</p><p>The rejected chain preserves request identity, validation stages, explicit outcome, elapsed time, evidence beyond the session, and separation between governance evidence and generated SQL. It demonstrates that a real application can persist governance-related records, reconstruct a multi-stage chain, retain rejection as a first-class outcome, and display policy gates. It does not establish full TMPA Core conformance, representative SME performance, independent adoption, cryptographic non-repudiation, or factual correctness of every record.</p><h1 id="_6-public-s0-4-c01–c14-corpus" tabindex="-1">6. Public S0.4 C01–C14 Corpus <a class="header-anchor" href="#_6-public-s0-4-c01–c14-corpus" aria-label="Permalink to &quot;6. Public S0.4 C01–C14 Corpus&quot;">​</a></h1><p>I0.3 described a local <code>tmpa-conformance.zip</code>, but that archive, its runner, and its fixtures were not present in the GitHub single source of truth. I0.4 replaces that unavailable delivery claim with the public repository corpus <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>, corpus ID <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>.</p><p>The corpus has two deliberately separate evidence tracks:</p><ol><li><strong>S0.4 Reference Reader track.</strong> A read-only implementation consumes synthetic fixtures, validates the public S0.4 schemas and executable profile, reconstructs canonical nodes, edges, issues, judgments, and views, then checks C01–C14 assertions.</li><li><strong>Pinned product-baseline track.</strong> Machine-readable assertions re-adjudicate the available FCoP, CodeFlowMu, and XiaoDian evidence against the stricter S0.4 criteria. A fixture PASS is never promoted into a product PASS.</li></ol><p>The repository command is <code>npm run tmpa:s0.4:conformance</code>. It regenerates criterion records, reference and product results, an execution log, a summary, and a SHA-256 file manifest without modifying product repositories. The runner uses strict JSON Schema validation for the S0.4 object and reader-result envelopes and validates the executable lifecycle/type/role/relation profile before evaluation.</p><p>Status semantics are strict: PASS means all mandatory assertions for that track executed and matched; PARTIAL means genuine product evidence exists but at least one S0.4-required observation or output is missing; NOT RUN means the required product execution path was unavailable; FAIL means an executed mandatory assertion did not match. The product aggregate is PASS only if all C01–C14 product verdicts are PASS.</p><p>The FCoP <code>3.2.4</code> commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code> was retrieved directly and rerun on Python 3.12.13: <strong>1,137 passed, 2 skipped, 0 failed</strong>. The pinned CodeFlowMu <code>V1.2.3</code> commit <code>8f342d028eb66e77d135bea58fdbc7f2d0627e3b</code> was not retrievable from the public <code>CodeFlowMu-open</code> history, so I0.4 records the new CodeFlowMu run as NOT RUN and uses preserved I0.3 assertions only for bounded re-adjudication.</p><table tabindex="0"><thead><tr><th>Evidence track</th><th style="text-align:right;">PASS</th><th style="text-align:right;">PARTIAL</th><th style="text-align:right;">NOT RUN</th><th style="text-align:right;">FAIL</th><th>Aggregate</th><th>Claim level</th></tr></thead><tbody><tr><td>S0.4 Reference Reader fixtures</td><td style="text-align:right;">14</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>PASS</td><td>Implemented and author-demonstrated</td></tr><tr><td>FCoP–CodeFlowMu product baseline</td><td style="text-align:right;">1</td><td style="text-align:right;">9</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td>PARTIAL</td><td>Mixed product evidence</td></tr></tbody></table><p>The Reference Reader result demonstrates that the published interpretation is executable. It does <strong>not</strong> establish that FCoP, CodeFlowMu, or XiaoDian fully conforms to S0.4, and it does not establish independent adoption.</p><h1 id="_7-criterion-level-results" tabindex="-1">7. Criterion-Level Results <a class="header-anchor" href="#_7-criterion-level-results" aria-label="Permalink to &quot;7. Criterion-Level Results&quot;">​</a></h1><p>The test names and meanings below are direct references to Core Specification Section 10.2; this report records only product evidence and remaining gaps.</p><table tabindex="0"><thead><tr><th>ID</th><th>Canonical test name</th><th>Verdict</th><th>Product evidence and remaining gap</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td>PARTIAL</td><td>FCoP and CodeFlowMu provide schemas and validation paths, but complete TMPA canonical-object coverage and all negative format cases are not yet exposed through one Core validator.</td></tr><tr><td>C02</td><td>Primary-carrier and single-writer immutability</td><td>PARTIAL</td><td>Separate artifacts and correction evidence exist; stricter immutable-object and one-primary-carrier observation remains incomplete.</td></tr><tr><td>C03</td><td>Duplicate object identity</td><td>PARTIAL</td><td>Duplicate and conflict mechanisms exist locally, but a canonical same-ID/different-content quarantine view is not exposed end to end.</td></tr><tr><td>C04</td><td>Serial-stream continuity and asynchronous progress</td><td>PARTIAL</td><td>Local ordering, dependency waiting, and asynchronous progress are implemented; one canonical partial-order graph and stream-gap issue set are not yet emitted.</td></tr><tr><td>C05</td><td>Role authority</td><td>PARTIAL</td><td>Role, capability, and operation gates exist; all failures are not yet normalized into one authoritative TMPA issue model.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td>PARTIAL</td><td>Direct lifecycle tests cover illegal and unauthorized transitions, but the product evidence does not yet emit both required canonical outputs: <code>ILLEGAL_TRANSITION</code>/<code>invalid</code> and <code>LIFECYCLE_UNDETERMINED</code>/<code>undetermined</code>.</td></tr><tr><td>C07</td><td>Separation of duties</td><td>PARTIAL</td><td>Separate reports and reviews plus review gates exist, but complete identity-level separation and exception-object handling are not fully demonstrated.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td>NOT RUN</td><td>Fixture oracle exists; product covered-content digest verification and canonical tamper reader were not executed.</td></tr><tr><td>C09</td><td>Missing reference</td><td>PARTIAL</td><td>Missing dependencies can block work, but the complete <code>undetermined</code>/partial graph propagation and canonical issue output remain incomplete.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td>NOT RUN</td><td>Prohibited-cycle fixture exists; product graph reader capable of quarantining only the affected subgraph was not available.</td></tr><tr><td>C11</td><td>Aggregation and reconstruction determinism</td><td>NOT RUN</td><td>The fixture oracle produced byte-equivalent output across 24 permutations; no product-level canonical graph-plus-issue serializer was available.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td>NOT RUN</td><td>Conflict-preservation fixture exists; product-level deterministic disputed/<code>undetermined</code> view and authorized resolution path were not executed as one criterion.</td></tr><tr><td>C13</td><td>Recovery</td><td>PARTIAL</td><td>Restart and recovery mechanisms exist, but no unified fresh reader reconstructs all responsibility, lifecycle, dependency, and issue state.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td>PASS</td><td>Direct archive/history tests preserve terminal state, transitions, prior reports, reviews, and task evidence.</td></tr></tbody></table><p>The separate S0.4 Reference Reader track passes all 14 synthetic fixture assertions. Those results validate the executable interpretation and deterministic runner, not the products listed in the table.</p><h1 id="_8-product-projection-gap" tabindex="-1">8. Product Projection Gap <a class="header-anchor" href="#_8-product-projection-gap" aria-label="Permalink to &quot;8. Product Projection Gap&quot;">​</a></h1><p>The publication repository now contains a generic S0.4 read-only Reference Reader. The dominant product gap is therefore narrower and more concrete: neither pinned product has a maintained projection adapter that converts its native artifacts into the S0.4 source-object surface consumed by that reader.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source artifacts</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>source candidates with retained provenance</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>canonical candidate set</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>partial-order process and responsibility graph</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>canonical issue set</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>valid / invalid / undetermined judgment</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>authoritative / quarantined / partial / disputed / pending_human view</span></span></code></pre></div><p>FCoP and CodeFlowMu already provide substantial write-side and local-control mechanisms: separate artifacts, atomic publication, role checks, lifecycle gates, dependency blocking, archive preservation, and restart recovery. Product-specific projection would directly improve C03, C05, C09, and C13, provide infrastructure for C04/C07, and create the product execution path required by C10–C12. C01 still has schema-coverage gaps; C02 has a stricter immutability gap; C06 lacks the complete canonical three-valued output pair; C08 requires covered-content digest evidence. CodeFlowMu additionally needs a publicly retrievable pinned source or reproduction package.</p><h1 id="_9-three-valued-governance-in-the-worked-flow" tabindex="-1">9. Three-Valued Governance in the Worked Flow <a class="header-anchor" href="#_9-three-valued-governance-in-the-worked-flow" aria-label="Permalink to &quot;9. Three-Valued Governance in the Worked Flow&quot;">​</a></h1><p>TMPA distinguishes semantic judgment from view classification:</p><table tabindex="0"><thead><tr><th>Semantic judgment</th><th>View classification</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>required evidence and rules establish the conclusion</td></tr><tr><td><code>invalid</code></td><td>quarantined or rejected</td><td>a deterministic violation excludes the affected evidence or action</td></tr><tr><td><code>undetermined</code></td><td>partial</td><td>required evidence is missing or incomplete</td></tr><tr><td><code>undetermined</code></td><td>disputed</td><td>valid evidence conflicts and no authorized resolution exists</td></tr><tr><td><code>undetermined</code></td><td>pending_human</td><td>the applicable profile requires a human decision</td></tr></tbody></table><p>A representative review flow is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK → REPORT → QA REVIEW(needs_human)</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>          judgment: undetermined</span></span>
<span class="line"><span>          view: pending_human</span></span>
<span class="line"><span>          lifecycle: blocked_pending_resolution</span></span>
<span class="line"><span>                       ↓</span></span>
<span class="line"><span>              ADMIN DECISION</span></span>
<span class="line"><span>             ↙              ↘</span></span>
<span class="line"><span>        approve             reject</span></span>
<span class="line"><span>          ↓                   ↓</span></span>
<span class="line"><span>        valid              invalid</span></span></code></pre></div><p>The <code>needs_human</code> state remains present in the graph and queryable. It is not prematurely represented as done, approved, failed, or rejected. Any downstream object that depends on the unresolved review remains <code>undetermined</code> until an authorized decision object is added.</p><p>The S0.4 Reference Reader demonstrates this three-valued flow on synthetic fixtures. Current CodeFlowMu behavior includes human-attention and waiting states, but product normalization into the Core judgment/view model remains an implementation target rather than a fully demonstrated product claim.</p><h1 id="_10-wp-13-multi-agent-evidence-gating-under-uncertain-tool-results" tabindex="-1">10. WP-13: Multi-Agent Evidence Gating under Uncertain Tool Results <a class="header-anchor" href="#_10-wp-13-multi-agent-evidence-gating-under-uncertain-tool-results" aria-label="Permalink to &quot;10. WP-13: Multi-Agent Evidence Gating under Uncertain Tool Results&quot;">​</a></h1><h2 id="_10-1-research-question-and-unit-of-observation" tabindex="-1">10.1 Research Question and Unit of Observation <a class="header-anchor" href="#_10-1-research-question-and-unit-of-observation" aria-label="Permalink to &quot;10.1 Research Question and Unit of Observation&quot;">​</a></h2><p>WP-13 records a field event with direct relevance to TMPA three-valued governance. A subexecution produced a completion-meaning summary after its tool lifecycle ended, while the same raw event retained <code>no exit status</code>, unconfirmed tests, and an unavailable commit SHA. The research question is not why a model produced an inaccurate sentence. It is:</p><blockquote><p>When an agent claim and persistent work facts do not close, can multi-agent governance prevent the unverified claim from entering the authoritative delivery chain?</p></blockquote><p>The observation window is 2026-08-05 12:59–13:11 (Asia/Shanghai). The public evidence set preserves two tasks, DEV and QA reports, the raw subexecution JSONL, a 300-line runtime excerpt, a Git patch and manifest, five QA JSON files, a session transcript, and explicit boundary notes. It is author-produced engineering evidence, not a third-party audit.</p><h2 id="_10-2-from-unconfirmed-claim-to-reviewable-delivery" tabindex="-1">10.2 From Unconfirmed Claim to Reviewable Delivery <a class="header-anchor" href="#_10-2-from-unconfirmed-claim-to-reviewable-delivery" aria-label="Permalink to &quot;10.2 From Unconfirmed Claim to Reviewable Delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Observable fact</th><th>Governance result</th></tr></thead><tbody><tr><td>DEV subexecution</td><td>the tool event ended, but inner commands lacked confirmed exit status; tests and SHA were unconfirmed</td><td>tool completion did not establish business completion</td></tr><tr><td>PM fact check</td><td>no formal DEV report, required test files absent, and Git HEAD still at the previous work package</td><td>no release, no QA dispatch, and no duplicate task</td></tr><tr><td>Same-task recovery</td><td>after tool-channel recovery, DEV completed implementation, tests, commit <code>609571dd…</code>, and <code>REPORT-037</code></td><td>delivery acquired externally checkable facts</td></tr><tr><td>Role-separated QA</td><td><code>QA-01</code> reran 27 tests, typecheck, and diff check against <code>DEV-01</code> delivery</td><td>27/27 PASS; typecheck 0; diff check 0</td></tr></tbody></table><p>This chain does not show that the model ceased making errors. It demonstrates <strong>governance-layer containment</strong>: natural-language claims remain candidate evidence, and they do not change authoritative delivery state until task, report, Git, and test facts close.</p><h2 id="_10-3-tmpa-three-valued-interpretation" tabindex="-1">10.3 TMPA Three-Valued Interpretation <a class="header-anchor" href="#_10-3-tmpa-three-valued-interpretation" aria-label="Permalink to &quot;10.3 TMPA Three-Valued Interpretation&quot;">​</a></h2><p>In a retrospective S0.4 analysis of observation time <code>τ₀</code>, the conclusion &quot;WP-13 is complete&quot; should not be <code>valid</code>, because mandatory evidence was absent or unreadable. It should not automatically be <code>invalid</code>, because the implementation itself had not yet been proven to violate acceptance rules. The appropriate semantic value is <code>undetermined</code>, with a <code>partial</code> operational view; PM waits for evidence and does not release.</p><p>This is an analytical S0.4 projection of field evidence, not a claim that CodeFlowMu emitted a canonical Reader envelope at the time. The native system did not publish <code>LIFECYCLE_UNDETERMINED</code>, a canonical issue set, and a three-valued result bound to a fixed profile. The case therefore does not upgrade C06 to PASS.</p><h2 id="_10-4-tmpa-to-fcop-to-codeflowmu" tabindex="-1">10.4 TMPA to FCoP to CodeFlowMu <a class="header-anchor" href="#_10-4-tmpa-to-fcop-to-codeflowmu" aria-label="Permalink to &quot;10.4 TMPA to FCoP to CodeFlowMu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Realization in this case</th></tr></thead><tbody><tr><td>TMPA</td><td>separates claims, evidence, and authoritative judgment; incomplete mandatory evidence remains <code>undetermined</code></td></tr><tr><td>FCoP</td><td>TASK is the stable primary carrier, REPORT is published separately, and <code>references</code>/<code>depends_on</code> retain task-report relations</td></tr><tr><td>CodeFlowMu</td><td>runtime records tool events and task state; PM performs business fact checking; DEV resumes the original task; QA verifies under a separate role</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Evidence dimension</th><th>Specified</th><th>Implemented</th><th>Demonstrated</th><th>Independently Adopted</th></tr></thead><tbody><tr><td>three-valued judgment under incomplete evidence</td><td>S0.4</td><td>local waiting/review controls exist</td><td>WP-13 retrospective analysis</td><td>no</td></tr><tr><td>persistent TASK/REPORT fact chain</td><td>FCoP profile</td><td>yes</td><td>yes</td><td>no</td></tr><tr><td>DEV–PM–QA separation of duties</td><td>S0.4/FCoP profile</td><td>yes</td><td><code>DEV-01</code>/PM/<code>QA-01</code></td><td>no</td></tr><tr><td>same-task recovery and evidence completion</td><td>S0.4 recovery objective</td><td>yes</td><td>yes</td><td>no</td></tr><tr><td>WP-13 product projection adapter and canonical Reader output</td><td>S0.4</td><td>no</td><td>no</td><td>no</td></tr></tbody></table><h2 id="_10-5-contribution-to-c01–c14-evidence" tabindex="-1">10.5 Contribution to C01–C14 Evidence <a class="header-anchor" href="#_10-5-contribution-to-c01–c14-evidence" aria-label="Permalink to &quot;10.5 Contribution to C01–C14 Evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>Incremental WP-13 evidence</th><th>I0.5 verdict effect</th></tr></thead><tbody><tr><td>C04</td><td>TASK-019 → REPORT-037 → TASK-020 → REPORT-038 plus runtime events form a traceable serial chain</td><td>strengthens demonstrated evidence; remains PARTIAL</td></tr><tr><td>C06</td><td>authoritative delivery state does not advance while mandatory evidence is insufficient</td><td>no canonical issue code or Reader result; remains PARTIAL</td></tr><tr><td>C07</td><td>DEV delivery, PM fact checking, and QA verification occur under separate work roles</td><td>field demonstration of role separation; authenticated identity and exception objects remain missing, so PARTIAL</td></tr><tr><td>C09</td><td>required report, commit, and test evidence is missing at the intermediate observation</td><td>supports incomplete-evidence analysis but emits no canonical <code>MISSING_REFERENCE</code>; remains PARTIAL</td></tr><tr><td>C13</td><td>after tool recovery, the original task continues and adds Git, report, and QA evidence</td><td>strengthens recovery evidence; no fresh-reader equivalence, so PARTIAL</td></tr><tr><td>C08/C11/C12</td><td>unsigned checksums, raw/readable projection comparison, and retained conflicting claims are supporting materials</td><td>do not substitute for product-criterion execution; remain NOT RUN</td></tr></tbody></table><p>The case adds no adjudicable evidence for the remaining criteria. I0.5 therefore preserves the I0.4 aggregate product result and does not relabel prior unexecuted criteria.</p><h2 id="_10-6-evidence-boundaries" tabindex="-1">10.6 Evidence Boundaries <a class="header-anchor" href="#_10-6-evidence-boundaries" aria-label="Permalink to &quot;10.6 Evidence Boundaries&quot;">​</a></h2><ul><li>QA is role-separated verification, not external third-party independent validation.</li><li><code>dev-report-037.md</code> and <code>qa-report-038.md</code> retain <code>runtime_bound: False</code>; they are not runtime-authenticated evidence.</li><li>At the evidence snapshot endpoint, TASK-019 and TASK-020 are both <code>review / pending</code>. The package establishes DEV delivery and role-separated QA PASS, not terminal approval or archive within the snapshot.</li><li>Same-bundle unsigned checksums establish only internal consistency, not publisher identity, source authenticity, or a trusted timestamp.</li><li>The case demonstrates containment of an unverified completion claim, not prevention or elimination of all model hallucinations.</li></ul><p>The complete byte-preserved package is downloadable as <a href="/joinwell52/evidence/tmpa/i0.5/wp13-multi-agent-fact-check-publication-evidence-v3.zip">WP-13 Publication Evidence V3</a>, with outer SHA-256 <code>5b5eda3034c822f13421783244b1d0c76a9fa79950bfad0ce61bb8d2e404131c</code>.</p><h1 id="_11-reproducibility-and-limitations" tabindex="-1">11. Reproducibility and Limitations <a class="header-anchor" href="#_11-reproducibility-and-limitations" aria-label="Permalink to &quot;11. Reproducibility and Limitations&quot;">​</a></h1><p>The S0.4 corpus is now public at a stable repository path and includes one-command execution, schemas, profile, fixtures, assertions, outputs, logs, and SHA-256 manifests. Repeated local executions with the fixed execution timestamp produce byte-identical artifacts. The FCoP commit was independently retrieved within this maintenance run and its selected test suites reran successfully; the CodeFlowMu commit was unavailable from the public repository. No third party has rerun or independently validated the corpus.</p><p>The baseline does not establish representative SME performance, comparative deployment cost, broad fault tolerance, independent adoption, factual truth of participant claims, authenticated identity, protected storage, or Byzantine resilience. Product and case evidence remain author-produced. The public demonstration and private data-producing system are not asserted to be one reproducible public build.</p><p>Required next measurements include installation dependencies and time, first-team startup, CPU/memory/storage growth, reconstruction under delayed and permuted evidence, controlled interruption and restart, conflict and missing-reference injection, human inspectability, adoption burden, and comparison against chat/shared-folder/simple-workflow baselines.</p><h1 id="_12-engineering-roadmap" tabindex="-1">12. Engineering Roadmap <a class="header-anchor" href="#_12-engineering-roadmap" aria-label="Permalink to &quot;12. Engineering Roadmap&quot;">​</a></h1><ol><li>Implement maintained FCoP and CodeFlowMu projection adapters without changing existing write behavior.</li><li>Publish or otherwise make the pinned CodeFlowMu source and reproduction package retrievable.</li><li>Execute product-level C08, C10, C11, and C12.</li><li>Emit the missing canonical outputs for C01–C07, C09, and C13, including both C06 three-valued branches.</li><li>Measure low-resource deployment, restart, and incremental reconstruction.</li><li>Obtain an independent rerun and record all differences.</li></ol><h1 id="_13-evidence-statement" tabindex="-1">13. Evidence Statement <a class="header-anchor" href="#_13-evidence-statement" aria-label="Permalink to &quot;13. Evidence Statement&quot;">​</a></h1><p>This report provides versioned engineering evidence, not independent validation. Its strongest results are bounded: the public S0.4 Reference Reader passes 14 of 14 synthetic criteria; the pinned product baseline has C14 PASS, nine PARTIAL verdicts, four NOT RUN verdicts, and no observed FAIL. Zero FAIL does not mean complete conformance because four product criteria were not executed and nine remain incomplete. Stronger claims require product projection, CodeFlowMu reproducibility, broader experiments, and independent reproduction.</p><h1 id="_14-engineering-conclusion" tabindex="-1">14. Engineering Conclusion <a class="header-anchor" href="#_14-engineering-conclusion" aria-label="Permalink to &quot;14. Engineering Conclusion&quot;">​</a></h1><p>The public S0.4 corpus converts broad engineering history into a testable, repository-resident baseline. Its Reference Reader passes all 14 synthetic criteria. Against the pinned products, only C14 passes, nine criteria have partial evidence, and four were not run at product-reader level. The result is stronger than an unversioned demonstration but remains weaker than complete or independent conformance.</p><p>The products already contain many write-side and local-control mechanisms. The new generic reader establishes a deterministic read-side reference, while maintained product projection adapters remain the largest shared gap. Product execution of C08, C10, C11, and C12, completion of the other partial outputs, quantified SME deployment cost, and independent reproduction remain separate empirical requirements.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The author-produced S0.4 corpus is public at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>. It contains the Reference Reader, executable profile, fixtures, product-evidence assertions, external-run records, criterion results, summaries, logs, and SHA-256 manifest. WP-13 case boundaries and mapping metadata are at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/cases/wp13-multi-agent-fact-check" target="_blank" rel="noreferrer"><code>research/cases/wp13-multi-agent-fact-check</code></a>, and the complete V3 package is published under <code>/evidence/tmpa/i0.5/</code>. There is no separate <code>tmpa-conformance.zip</code>; Git history is the version history.</p><h1 id="data-availability" tabindex="-1">Data Availability <a class="header-anchor" href="#data-availability" aria-label="Permalink to &quot;Data Availability&quot;">​</a></h1><p>The public demonstration exposes selected governance views. Private business data, credentials, and sensitive operational records are not included. The corpus uses selected test paths, hash inventories, and compact fixtures rather than exporting private production data. The WP-13 package contains only the tasks, reports, runtime excerpts, Git patch, and QA results needed for this case; the original private product repository is not distributed with it.</p><h1 id="competing-interests-and-provenance" tabindex="-1">Competing Interests and Provenance <a class="header-anchor" href="#competing-interests-and-provenance" aria-label="Permalink to &quot;Competing Interests and Provenance&quot;">​</a></h1><p>The author is the originator or principal developer of TMPA, FCoP, and CodeFlowMu and is involved in the XiaoDian AI lineage. All baseline results are author-produced. This relationship increases the need for fixed versions, preserved failures, and independent reproduction.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] FCoP Project. “FCoP — File-based Coordination Protocol,” repository README and architecture stack. GitHub, 2026. <code>https://github.com/joinwell52-AI/FCoP</code>.</p><p>[2] FCoP Project. “FCoP Runtime Specification · Single-Page Complete Edition,” 1.2.x specification line, 2026.</p><p>[3] FCoP Project. “FCoP IPC Envelope” and related machine-readable JSON Schemas, <code>spec/schemas/</code>, 2026.</p><p>[4] Python Package Index. <code>fcop</code> and <code>fcop-mcp</code> distributions, 2026.</p><p>[5] Official MCP Registry. <code>io.github.joinwell52-AI/fcop</code>, <code>fcop-mcp</code> server entry, 2026.</p><p>[6] FCoP Project. “ADR-0031: Governance Alert Layer (GAL).” Accepted 2026-05-11.</p><p>[7] FCoP Project. “ADR-0032: <code>fcop_audit()</code> — Protocol-to-Inspection Compiler.” Accepted 2026-05-12.</p><p>[8] CodeFlowMu. “TMPA Browser” public demonstration. <code>https://demo.chedian.cc/</code>. Snapshot observed 2026-07-29.</p><p>[9] TMPA Project. “TMPA Core S0.4 C01–C14 Conformance Corpus.” Corpus ID <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>, executed 2026-08-03. <code>research/conformance/tmpa-core-s0.4/</code>.</p><p>[10] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” Author-produced evidence snapshot, observed 2026-08-05. <code>research/cases/wp13-multi-agent-fact-check/</code>.</p><h1 id="appendix-a-fcop-end-to-end-artifact-example" tabindex="-1">Appendix A. FCoP End-to-End Artifact Example <a class="header-anchor" href="#appendix-a-fcop-end-to-end-artifact-example" aria-label="Permalink to &quot;Appendix A. FCoP End-to-End Artifact Example&quot;">​</a></h1><p>A TASK is created by PM, claimed and executed by DEV, followed by a separate DEV REPORT and an independent QA REVIEW. The QA review may return <code>needs_human</code> when technical verification passes but production activation changes an authorization boundary.</p><p>The reader reconstructs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK created by PM</span></span>
<span class="line"><span>  ├─ claimed and executed by DEV</span></span>
<span class="line"><span>  ├─ REPORT submitted by DEV</span></span>
<span class="line"><span>  ├─ REVIEW issued by QA: needs_human</span></span>
<span class="line"><span>  ├─ judgment: undetermined</span></span>
<span class="line"><span>  ├─ view: pending_human</span></span>
<span class="line"><span>  ├─ authorized human approval or rejection evidence</span></span>
<span class="line"><span>  └─ final judgment: valid or invalid</span></span></code></pre></div><p>The <code>needs_human</code> node remains in the graph and is queryable. Downstream objects depending on it remain <code>undetermined</code> until an authorized decision object resolves the state. The authoritative record is the source set and transitions, not the rendered view. Reordering input files must not change the reconstructed graph or issue set.</p><h2 id="i0-5-theory-to-implementation-alignment" tabindex="-1">I0.5 Theory-to-Implementation Alignment <a class="header-anchor" href="#i0-5-theory-to-implementation-alignment" aria-label="Permalink to &quot;I0.5 Theory-to-Implementation Alignment&quot;">​</a></h2><p>FCoP is evaluated as a protocol realization of TMPA concepts; CodeFlowMu is evaluated as an engineering system combining protocol roles with Skills, tools, runtime execution, recovery, and interfaces. The report distinguishes probabilistic agent execution evidence from deterministic validation mechanisms, and demonstrated behavior from full Core conformance.</p>`,117))])}const g=a(s,[["render",c]]);export{b as __pageData,g as default};
